<?php
function register_notification_routes($router,$pdo,$config){
 $router->get('/notifications',function()use($pdo,$config){$uid=Security::requireUser();$svc=new NotificationService($pdo);$page=isset($_GET['page'])&&is_scalar($_GET['page'])?max(1,(int)$_GET['page']):1;$filter=isset($_GET['read'])&&is_string($_GET['read'])&&in_array($_GET['read'],array('unread','read'),true)?$_GET['read']:'';$type=isset($_GET['type'])&&is_string($_GET['type'])&&in_array($_GET['type'],array('feedback_review','feedback_progress','ticket_update','ticket_reply','ticket_closed','order_paid','order_delivered','order_refunded','system'),true)?$_GET['type']:'';$data=$svc->paginate($uid,$page,20,$filter,$type);$rows='';$qs=function($r,$t,$p=1){$v=array();if($r!=='')$v[]='read='.rawurlencode($r);if($t!=='')$v[]='type='.rawurlencode($t);if($p>1)$v[]='page='.(int)$p;return '/notifications'.($v?'?'.implode('&',$v):'');};foreach($data['items'] as $n){$path=$svc->targetPath($n);$title=e($n['title']);if($path)$title='<a href="'.e($path).'">'.$title.'</a>';$rows.='<article class="notification-item'.(empty($n['read_at'])?' unread':'').'"><h2>'.$title.'</h2><p>'.nl2br(e($n['content'])).'</p><small>'.e($n['created_at']).'</small>'.(empty($n['read_at'])?'<form method="post" action="/notifications/'.(int)$n['id'].'/read">'.csrf_field().'<input type="hidden" name="read" value="'.e($filter).'"/><input type="hidden" name="type" value="'.e($type).'"/><input type="hidden" name="page" value="'.(int)$data['page'].'"/><button class="secondary-button">标为已读</button></form>':'').'</article>';}$body='<div class="notifications-page"><header class="ux-page-head"><div><h1>消息中心</h1><p>个人消息仅本人可见；公告请查看系统公告。</p></div><form method="post" action="/notifications/read-all">'.csrf_field().'<input type="hidden" name="read" value="'.e($filter).'"/><input type="hidden" name="type" value="'.e($type).'"/><input type="hidden" name="page" value="'.(int)$data['page'].'"/><button class="secondary-button">全部标为已读</button></form></header><nav class="notification-filters" aria-label="消息筛选"><a'.($filter===''&&$type===''?' class="service-ui-selected" aria-current="page"':'').' href="/notifications">全部</a> <a'.($filter==='unread'?' class="service-ui-selected" aria-current="true"':'').' href="'.$qs('unread',$type).'">未读</a> <a'.($filter==='read'?' class="service-ui-selected" aria-current="true"':'').' href="'.$qs('read',$type).'">已读</a> <a'.($type==='feedback_review'?' class="service-ui-selected" aria-current="true"':'').' href="'.$qs($filter,'feedback_review').'">反馈审核</a> <a'.($type==='feedback_progress'?' class="service-ui-selected" aria-current="true"':'').' href="'.$qs($filter,'feedback_progress').'">反馈进度</a> <a'.($type==='ticket_update'?' class="service-ui-selected" aria-current="true"':'').' href="'.$qs($filter,'ticket_update').'">工单</a> <a href="/announcements">系统公告</a></nav><section class="notification-list" aria-label="消息列表">'.($rows?:'<div class="empty service-ui-empty"><h2>'.($filter!==''||$type!==''?'当前筛选下暂无消息':'暂无消息').'</h2><p>订单、反馈和工单的相关消息将在这里展示。</p><a class="secondary-button" href="'.($filter!==''||$type!==''?'/notifications':'/announcements').'">'.($filter!==''||$type!==''?'查看全部消息':'查看系统公告').'</a></div>').'</section><nav class="service-ui-pagination" aria-label="消息分页"><span>共'.(int)$data['total'].' 条 · 第 '.(int)$data['page'].' / '.(int)$data['pages'].' 页</span> '.($data['page']>1?'<a rel="prev" href="'.$qs($filter,$type,$data['page']-1).'">上一页</a> ':'').($data['page']<$data['pages']?'<a rel="next" href="'.$qs($filter,$type,$data['page']+1).'">下一页</a>':'').'</nav></div>';page('消息中心',$body,$config);});
 $router->post('/notifications/{id}/read',function($id)use($pdo){$uid=Security::requireUser();post_csrf();(new NotificationService($pdo))->markRead($uid,(int)$id);$r=isset($_POST['read'])&&is_string($_POST['read'])&&in_array($_POST['read'],array('unread','read'),true)?$_POST['read']:'';$t=isset($_POST['type'])&&is_string($_POST['type'])&&in_array($_POST['type'],array('feedback_review','feedback_progress','ticket_update','ticket_reply','ticket_closed','order_paid','order_delivered','order_refunded','system'),true)?$_POST['type']:'';$p=isset($_POST['page'])&&is_scalar($_POST['page'])?max(1,(int)$_POST['page']):1;redirect('/notifications?read='.rawurlencode($r).'&type='.rawurlencode($t).'&page='.$p);});
 $router->post('/notifications/read-all',function()use($pdo){$uid=Security::requireUser();post_csrf();(new NotificationService($pdo))->markAllRead($uid);$r=isset($_POST['read'])&&is_string($_POST['read'])&&in_array($_POST['read'],array('unread','read'),true)?$_POST['read']:'';$t=isset($_POST['type'])&&is_string($_POST['type'])&&in_array($_POST['type'],array('feedback_review','feedback_progress','ticket_update','ticket_reply','ticket_closed','order_paid','order_delivered','order_refunded','system'),true)?$_POST['type']:'';$p=isset($_POST['page'])&&is_scalar($_POST['page'])?max(1,(int)$_POST['page']):1;redirect('/notifications?read='.rawurlencode($r).'&type='.rawurlencode($t).'&page='.$p);});
}
